SELECT t.tourId, t.catalogueId, t.title, t.destination, t.description, t.price, t.createdBy, (SELECT i.imageUrl FROM images i WHERE i.tourId = t.tourId AND i.isPrimary = TRUE LIMIT 1) as primaryImageUrl FROM tours t
INNER JOIN catalogues c ON t.catalogueId = c.catalogueId
AND t.tourId = #{tourId}
AND t.catalogueId = #{catalogueId}
AND c.title = #{catalogueName}
AND t.title LIKE CONCAT('%', #{title}, '%')
AND t.destination LIKE CONCAT('%', #{destination}, '%')
AND t.price >= #{minPrice}
AND t.price <= #{maxPrice}
ORDER BY t.updateTime LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM tours t

    INNER JOIN catalogues c ON t.catalogueId = c.catalogueId



